    }

    .apply-button {
      min-width: 78px;
      padding: 0 16px;
      color: var(--green-dark);
      background: var(--green-soft);
      border: 0;
      border-radius: 12px;
      font-weight: 700;
    }

    .promo-message {
      min-height: 24px;
      margin: 7px 2px 0;
      color: var(--green-dark);
      font-size: var(--label-size);
    }

    .summary {
      margin-top: 16px;
      padding: 18px;
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: 20px;
    }

    .summary-row {
      display: flex;
      justify-content: space-between;
      gap: 16px;
      padding: 8px 0;
      color: #4e5d56;
      font-size: 15px;
    }

    .summary-row span:last-child {
      white-space: nowrap;
      font-variant-numeric: tabular-nums;
    }

    .summary-divider {
      height: 1px;
      margin: 8px 0;
      background: var(--line);
    }

    .summary-row.total {
      align-items: baseline;
      padding-top: 14px;
      color: var(--ink);
      font-size: 18px;
      font-weight: 800;
    }

    .total-value {
      color: var(--green-dark);
      font-size: 20px;
      font-variant-numeric: tabular-nums;
    }

    .order-bar {
      position: fixed;
      z-index: 20;
      inset-inline: 0;
      bottom: 0;
      padding: 14px 16px calc(14px + env(safe-area-inset-bottom));
      background: rgba(255, 255, 255, 0.97);
      border-top: 1px solid var(--line);
      box-shadow: 0 -8px 24px rgba(28, 54, 43, 0.06);
      backdrop-filter: blur(12px);
    }

    .order-bar-inner {
      width: 100%;
      max-width: 448px;
      margin-inline: auto;
    }

    .order-button {
      display: flex;
      width: 100%;
      min-height: 56px;
      align-items: center;
      justify-content: center;
      gap: 10px;
      color: #fff;
      background: var(--green);
      border: 0;
      border-radius: 16px;
      box-shadow: 0 8px 20px rgba(8, 127, 91, 0.22);
      font-size: 17px;
      font-weight: 800;
    }

    .order-button:active {
      background: var(--green-dark);
      transform: translateY(1px);
    }

    .order-button svg {
      width: 20px;
      height: 20px;
    }

    .secure-note {
      margin: 7px 0 0;
      color: var(--muted);
      text-align: center;
      font-size: var(--label-size);
    }

    .toast {
      position: fixed;
      z-index: 30;
      inset-inline: 24px;
      bottom: calc(110px + env(safe-area-inset-bottom));
      max-width: 420px;
      margin-inline: auto;
      padding: 12px 16px;
      color: #fff;
      background: #17221e;
      border-radius: 14px;
      box-shadow: 0 10px 30px rgba(0,0,0,.2);
      text-align: center;
      opacity: 0;
      pointer-events: none;
      transform: translateY(10px);
      transition: .2s ease;
    }

    .toast.show {
      opacity: 1;
      transform: translateY(0);
    }

    @media (min-width: 480px) {
      body {
        padding: 18px 0;
      }

      .app {
        min-height: calc(100vh - 36px);
        overflow: hidden;
        border-radius: 28px;
        box-shadow: 0 18px 50px rgba(30, 67, 52, 0.12);
      }

      .order-bar {
        inset-inline: 50%;
        width: 480px;
        transform: translateX(-50%);
      }
    }

    @media (max-width: 360px) {
      .item {
        grid-template-columns: 64px minmax(0, 1fr);
      }

      .photo {
        width: 64px;
        height: 64px;
      }

      .price {
        grid-column: 2;
        padding-top: 0;
      }
    }
  </style>
