  <script>
    const items = Array.from(document.querySelectorAll('.item'));
    const subtotalEl = document.getElementById('subtotal');
    const vatEl = document.getElementById('vat');
    const totalEl = document.getElementById('total');
    const toast = document.getElementById('toast');
    const delivery = 12;
    let discount = 0;
    let toastTimer;

    function formatMoney(value) {
      return value.toLocaleString('en-AE', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      }) + ' د.إ';
    }

    function calculateSubtotal() {
      return items.reduce((sum, item) => {
        const quantity = Number(item.querySelector('.quantity').textContent);
        return sum + Number(item.dataset.price) * quantity;
      }, 0);
    }

    function updateSummary() {
      const subtotal = calculateSubtotal();
      const taxable = Math.max(0, subtotal - discount);
      const vat = taxable * 0.05;
      const total = taxable + delivery + vat;

      subtotalEl.textContent = formatMoney(subtotal);
      vatEl.textContent = formatMoney(vat);
      totalEl.textContent = formatMoney(total);
    }

    function showToast(message) {
      toast.textContent = message;
      toast.classList.add('show');
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => toast.classList.remove('show'), 2600);
    }

    items.forEach(item => {
      const quantityEl = item.querySelector('.quantity');
      const priceEl = item.querySelector('.price');
      const unitPrice = Number(item.dataset.price);

      item.querySelectorAll('.stepper button').forEach(button => {
        button.addEventListener('click', () => {
          let quantity = Number(quantityEl.textContent);
          quantity += button.dataset.action === 'increase' ? 1 : -1;
          quantity = Math.max(1, Math.min(99, quantity));
          quantityEl.textContent = quantity;
          priceEl.innerHTML = '<bdi>' + formatMoney(unitPrice * quantity) + '</bdi>';
          updateSummary();
        });
      });
    });

    document.getElementById('apply-promo').addEventListener('click', () => {
      const promo = document.getElementById('promo').value.trim().toUpperCase();
      const message = document.getElementById('promo-message');

      if (!promo) {
        discount = 0;
        message.textContent = 'أدخل رمز خصم أولًا.';
        updateSummary();
        return;
      }

      if (promo === 'GROCERY10') {
        discount = calculateSubtotal() * 0.10;
        message.textContent = 'تم تطبيق خصم 10%.';
      } else {
        discount = 0;
        message.textContent = 'رمز الخصم غير صالح.';
      }

      updateSummary();
    });

    document.getElementById('place-order').addEventListener('click', () => {
      showToast('تم إرسال طلبك للتأكيد.');
    });

    document.querySelector('.back-button').addEventListener('click', () => {
      showToast('تم الرجوع إلى السلة.');
    });
  </script>
